<template>
  <div class="dashboard">
    <!-- 欢迎区域 -->
    <div class="welcome-section">
      <!-- 主要内容区域：左侧欢迎信息 + 右侧操作按钮 -->
      <div class="welcome-main">
        <div class="welcome-header">
          <div class="user-avatar">
            <el-avatar :size="60" :src="authStore.user?.avatar_url">
              {{ authStore.user?.username?.charAt(0).toUpperCase() }}
            </el-avatar>
          </div>
          <div class="welcome-text">
            <h1 class="welcome-title">
              欢迎回来，{{ authStore.user?.username }}！
            </h1>
            <p class="welcome-subtitle">
              <span class="welcome-date">今天是 {{ currentDate }}</span>
              <span class="welcome-meta">让我们开始管理您的文件吧</span>
            </p>
          </div>
      </div>
      <div class="welcome-actions">
        <el-button type="primary" size="large" @click="goToFiles" class="action-btn primary">
          <el-icon><FolderOpened /></el-icon>
          浏览文件
        </el-button>
        <el-button size="large" @click="showUploadDialog = true" class="action-btn">
          <el-icon><Upload /></el-icon>
          上传文件
        </el-button>
        <el-button size="large" @click="createNewFolder" class="action-btn">
          <el-icon><FolderAdd /></el-icon>
          新建文件夹
        </el-button>
        <el-button 
          v-if="authStore.isAdmin" 
          size="large" 
          @click="goToAdmin" 
          class="action-btn admin-btn"
        >
          <el-icon><Setting /></el-icon>
          管理控制台
        </el-button>
      </div>
    </div>

    <!-- 统计数据区域：桌面端横向排列，移动端弧形轮播 -->
    <div class="welcome-stats">
      <!-- 桌面端一排显示 -->
      <div class="stat-item desktop-stat-item">
        <span class="stat-value">{{ stats.totalFiles }}</span>
        <span class="stat-label">总文件数</span>
      </div>
      <div class="stat-item desktop-stat-item">
        <span class="stat-value">{{ formatFileSize(stats.totalSize) }}</span>
        <span class="stat-label">已使用空间</span>
      </div>
      <div class="stat-item desktop-stat-item">
        <span class="stat-value">{{ formatPercentage(authStore.storageUsage) }}</span>
        <span class="stat-label">使用率</span>
      </div>
      <!-- 移动端弧形轮播 -->
      <div class="welcome-arc-wrapper">
        <div class="arc-track">
          <div
            v-for="(card, index) in welcomeStatCards"
            :key="card.key"
            class="arc-card"
            :class="getWelcomeArcClass(index)"
          >
            <div class="arc-card-inner">
              <div class="arc-card-header">
                <div class="arc-icon" :style="{ color: card.color }">
                  <el-icon><component :is="card.icon" /></el-icon>
                </div>
              </div>
              <div class="arc-number">{{ card.value }}</div>
              <div class="arc-label">{{ card.label }}</div>
            </div>
          </div>
        </div>
        <div class="arc-indicators">
          <span
            v-for="(card, index) in welcomeStatCards"
            :key="card.key"
            :class="['arc-dot', { active: welcomeArcIndex === index }]"
            @click="welcomeArcIndex = index"
          />
        </div>
      </div>
    </div>
    
    <!-- 统计卡片（桌面端网格布局） -->
    <div class="stats-grid stats-grid-desktop">
      <div class="stat-card image-card">
        <div class="card-header">
          <div class="stat-icon">
            <el-icon><Picture /></el-icon>
          </div>
          <div class="stat-trend">
            <el-icon :class="(Number(stats.changes?.images?.percentage) || 0) >= 0 ? 'trend-up' : 'trend-down'">
              <TrendCharts />
            </el-icon>
            <span class="trend-text" :class="(Number(stats.changes?.images?.percentage) || 0) >= 0 ? 'trend-positive' : 'trend-negative'">
              {{ (Number(stats.changes?.images?.percentage) || 0) >= 0 ? '+' : '' }}{{ (Number(stats.changes?.images?.percentage) || 0).toFixed(1) }}%
            </span>
          </div>
        </div>
        <div class="stat-content">
          <div class="stat-number">{{ stats.imageCount }}</div>
          <div class="stat-label">图片文件</div>
          <div class="stat-detail">{{ formatFileSize(stats.imageSize) }}</div>
        </div>
      </div>

      <div class="stat-card video-card">
        <div class="card-header">
          <div class="stat-icon">
            <el-icon><VideoPlay /></el-icon>
          </div>
          <div class="stat-trend">
            <el-icon :class="(Number(stats.changes?.videos?.percentage) || 0) >= 0 ? 'trend-up' : 'trend-down'">
              <TrendCharts />
            </el-icon>
            <span class="trend-text" :class="(Number(stats.changes?.videos?.percentage) || 0) >= 0 ? 'trend-positive' : 'trend-negative'">
              {{ (Number(stats.changes?.videos?.percentage) || 0) >= 0 ? '+' : '' }}{{ (Number(stats.changes?.videos?.percentage) || 0).toFixed(1) }}%
            </span>
          </div>
        </div>
        <div class="stat-content">
          <div class="stat-number">{{ stats.videoCount }}</div>
          <div class="stat-label">视频文件</div>
          <div class="stat-detail">{{ formatFileSize(stats.videoSize) }}</div>
        </div>
      </div>

      <div class="stat-card motion-card">
        <div class="card-header">
          <div class="stat-icon">
            <el-icon><CircleCheck /></el-icon>
          </div>
          <div class="stat-trend">
            <el-icon :class="(Number(stats.changes?.videos?.percentage) || 0) >= 0 ? 'trend-up' : 'trend-down'">
              <TrendCharts />
            </el-icon>
            <span class="trend-text" :class="(Number(stats.changes?.videos?.percentage) || 0) >= 0 ? 'trend-positive' : 'trend-negative'">
              {{ (Number(stats.changes?.videos?.percentage) || 0) >= 0 ? '+' : '' }}{{ (Number(stats.changes?.videos?.percentage) || 0).toFixed(1) }}%
            </span>
          </div>
        </div>
        <div class="stat-content">
          <div class="stat-number">{{ stats.motionCount || 0 }}</div>
          <div class="stat-label">动图/实况</div>
          <div class="stat-detail">{{ formatFileSize(stats.motionSize || 0) }}</div>
        </div>
      </div>

      <div class="stat-card folder-card">
        <div class="card-header">
          <div class="stat-icon">
            <el-icon><Folder /></el-icon>
          </div>
          <div class="stat-trend">
            <el-icon :class="(Number(stats.changes?.folders?.percentage) || 0) >= 0 ? 'trend-up' : 'trend-down'">
              <TrendCharts />
            </el-icon>
            <span class="trend-text" :class="(Number(stats.changes?.folders?.percentage) || 0) >= 0 ? 'trend-positive' : 'trend-negative'">
              {{ (Number(stats.changes?.folders?.percentage) || 0) >= 0 ? '+' : '' }}{{ (Number(stats.changes?.folders?.percentage) || 0).toFixed(1) }}%
            </span>
          </div>
        </div>
        <div class="stat-content">
          <div class="stat-number">{{ stats.folderCount }}</div>
          <div class="stat-label">文件夹</div>
          <div class="stat-detail">{{ stats.totalFiles }} 个文件</div>
        </div>
      </div>
    </div>

    <!-- 统计卡片（移动端弧形轮播） -->
    <div class="stats-arc-carousel" ref="carouselRef">
      <div class="arc-track">
        <div
          v-for="(card, index) in statCards"
          :key="card.key"
          :class="[
            'arc-card',
            card.cls,
            {
              active: currentArcIndex === index,
              [`left-${currentArcIndex - index}`]: currentArcIndex > index && currentArcIndex - index > 0 && currentArcIndex - index <= 3,
              [`right-${index - currentArcIndex}`]: currentArcIndex < index && index - currentArcIndex > 0 && index - currentArcIndex <= 3,
            }
          ]"
          @click="currentArcIndex = index"
        >
          <div class="arc-card-inner">
            <div class="arc-card-header">
              <div class="arc-icon" :style="{ color: card.color }">
                <el-icon><component :is="card.icon" /></el-icon>
              </div>
              <div class="arc-trend" :class="(card.percentage || 0) >= 0 ? 'trend-positive' : 'trend-negative'">
                <el-icon><TrendCharts /></el-icon>
                <span>{{ (card.percentage || 0) >= 0 ? '+' : '' }}{{ (card.percentage || 0).toFixed(1) }}%</span>
              </div>
            </div>
            <div class="arc-number">{{ card.value }}</div>
            <div class="arc-label">{{ card.label }}</div>
            <div class="arc-detail">{{ card.detail }}</div>
          </div>
        </div>
      </div>
      <!-- 指示点 -->
      <div class="arc-indicators">
        <span
          v-for="(card, index) in statCards"
          :key="card.key"
          :class="['arc-dot', { active: currentArcIndex === index }]"
          @click="currentArcIndex = index"
        />
      </div>
      <div class="arc-hint">← 左右滑动 →</div>
    </div>
  </div>

    <!-- 主要内容区域 -->
    <div class="main-content">
      <!-- 存储使用情况 -->
      <div class="storage-section">
        <el-card class="storage-card">
          <template #header>
            <div class="card-header">
              <div class="header-left">
                <el-icon class="header-icon"><PieChart /></el-icon>
                <h3>存储使用情况</h3>
              </div>
              <div class="header-actions">
                <el-button type="text" @click="goToFiles">
                  <el-icon><Setting /></el-icon>
                  管理文件
                </el-button>
              </div>
            </div>
          </template>
          
          <div class="storage-content">
            <div class="storage-overview">
              <div class="storage-info">
                <div class="storage-text">
                  <span class="used">{{ formatFileSize(authStore.user?.used_storage || 0) }}</span>
                  <span class="separator">/</span>
                  <span class="total">{{ formatFileSize(authStore.user?.storage_limit || 0) }}</span>
                </div>
                <div class="storage-percent">
                  {{ formatPercentage(authStore.storageUsage) }} 已使用
                </div>
              </div>
              
              <el-progress
                :percentage="authStore.storageUsage"
                :color="getStorageColor(authStore.storageUsage)"
                :stroke-width="16"
                class="storage-progress"
              >
                <template #default="{ percentage }">
                  {{ formatPercentage(percentage) }}
                </template>
              </el-progress>
            </div>
            
            <div class="storage-breakdown">
              <div class="breakdown-item">
                <div class="breakdown-icon image">
                  <el-icon><Picture /></el-icon>
                </div>
                <div class="breakdown-content">
                  <div class="breakdown-label">图片文件</div>
                  <div class="breakdown-value">{{ formatFileSize(stats.imageSize) }}</div>
                </div>
              </div>
              <div class="breakdown-item">
                <div class="breakdown-icon video">
                  <el-icon><VideoPlay /></el-icon>
                </div>
                <div class="breakdown-content">
                  <div class="breakdown-label">视频文件</div>
                  <div class="breakdown-value">{{ formatFileSize(stats.videoSize) }}</div>
                </div>
              </div>
              <div class="breakdown-item">
                <div class="breakdown-icon motion">
                  <el-icon><CircleCheck /></el-icon>
                </div>
                <div class="breakdown-content">
                  <div class="breakdown-label">动图/实况</div>
                  <div class="breakdown-value">{{ formatFileSize(stats.motionSize || 0) }}</div>
                </div>
              </div>
            </div>
            
            <div class="storage-tips">
              <el-alert
                v-if="authStore.storageUsage > 90"
                title="存储空间不足"
                type="warning"
                :closable="false"
                show-icon
              >
                您的存储空间即将用完，请及时清理不需要的文件或联系管理员扩容
              </el-alert>
              <el-alert
                v-else-if="authStore.storageUsage > 70"
                title="存储空间提醒"
                type="info"
                :closable="false"
                show-icon
              >
                您的存储空间已使用 {{ formatPercentage(authStore.storageUsage) }}，建议定期清理文件
              </el-alert>
              <el-alert
                v-else
                title="存储空间充足"
                type="success"
                :closable="false"
                show-icon
              >
                您的存储空间使用正常，还有 {{ formatPercentage(100 - authStore.storageUsage) }} 可用空间
              </el-alert>
            </div>
          </div>
        </el-card>
      </div>
      
      <!-- 趋势分析 -->
      <div class="trend-section">
        <el-card class="trend-card">
          <template #header>
            <div class="card-header">
              <div class="header-left">
                <el-icon class="header-icon"><TrendCharts /></el-icon>
                <h3>趋势分析</h3>
              </div>
              <div class="header-actions">
                <el-button type="text" @click="refreshTrends" :loading="loadingTrends">
                  <el-icon><Refresh /></el-icon>
                  刷新数据
                </el-button>
              </div>
            </div>
          </template>
          
          <div v-if="stats.trends.length > 0" class="trend-charts">
            <div class="chart-container">
              <div class="chart-title">文件数量趋势</div>
              <div class="chart-content">
                <div class="chart-bars">
                  <div 
                    v-for="(trend, index) in stats.trends" 
                    :key="index"
                    class="chart-bar"
                    :style="{ height: getBarHeight(trend.total_files, 'files') + '%' }"
                    :title="`${trend.trend_date}: ${trend.total_files} 个文件`"
                  >
                    <span class="bar-value">{{ trend.total_files }}</span>
                  </div>
                </div>
                <div class="chart-labels">
                  <span 
                    v-for="(trend, index) in stats.trends" 
                    :key="index"
                    class="chart-label"
                  >
                    {{ formatTrendDate(trend.trend_date) }}
                  </span>
                </div>
              </div>
            </div>
            
            <div class="chart-container">
              <div class="chart-title">存储使用趋势</div>
              <div class="chart-content">
                <div class="chart-bars">
                  <div 
                    v-for="(trend, index) in stats.trends" 
                    :key="index"
                    class="chart-bar storage-bar"
                    :style="{ height: getBarHeight(trend.total_size, 'size') + '%' }"
                    :title="`${trend.trend_date}: ${formatFileSize(trend.total_size)}`"
                  >
                    <span class="bar-value">{{ formatFileSize(trend.total_size) }}</span>
                  </div>
                </div>
                <div class="chart-labels">
                  <span 
                    v-for="(trend, index) in stats.trends" 
                    :key="index"
                    class="chart-label"
                  >
                    {{ formatTrendDate(trend.trend_date) }}
                  </span>
                </div>
              </div>
            </div>
          </div>
          
          <div v-else class="empty-state">
            <el-empty description="暂无趋势数据">
              <el-button type="primary" @click="loadDashboardData">
                <el-icon><Refresh /></el-icon>
                刷新数据
              </el-button>
            </el-empty>
          </div>
        </el-card>
      </div>

    <!-- 快速操作 -->
    <div class="quick-actions">
      <el-card class="actions-card">
        <template #header>
          <div class="card-header">
            <div class="header-left">
              <el-icon class="header-icon"><Lightning /></el-icon>
              <h3>快速操作</h3>
            </div>
          </div>
        </template>
        
        <div class="actions-grid">
          <div class="action-item" @click="showUploadDialog = true">
            <div class="action-icon">
              <el-icon><Upload /></el-icon>
            </div>
            <div class="action-content">
              <span class="action-text">上传文件</span>
              <span class="action-desc">拖拽或点击上传</span>
            </div>
          </div>
          
          <div class="action-item" @click="goToFiles">
            <div class="action-icon">
              <el-icon><FolderOpened /></el-icon>
            </div>
            <div class="action-content">
              <span class="action-text">浏览文件</span>
              <span class="action-desc">查看所有文件</span>
            </div>
          </div>
          
          <div class="action-item" @click="createNewFolder">
            <div class="action-icon">
              <el-icon><FolderAdd /></el-icon>
            </div>
            <div class="action-content">
              <span class="action-text">新建文件夹</span>
              <span class="action-desc">整理您的文件</span>
            </div>
          </div>
          
          <div class="action-item" @click="goToFiles">
            <div class="action-icon">
              <el-icon><Search /></el-icon>
            </div>
            <div class="action-content">
              <span class="action-text">搜索文件</span>
              <span class="action-desc">快速查找文件</span>
            </div>
          </div>
          
          <div class="action-item" @click="goToFiles">
            <div class="action-icon">
              <el-icon><Share /></el-icon>
            </div>
            <div class="action-content">
              <span class="action-text">分享文件</span>
              <span class="action-desc">生成分享链接</span>
            </div>
          </div>
          
          <div class="action-item" @click="goToFiles">
            <div class="action-icon">
              <el-icon><Download /></el-icon>
            </div>
            <div class="action-content">
              <span class="action-text">批量下载</span>
              <span class="action-desc">下载多个文件</span>
            </div>
          </div>
        </div>
      </el-card>
    </div>
  </div>

  <!-- 文件上传对话框 -->
  <el-dialog
    v-model="showUploadDialog"
    title="上传文件"
    :width="isMobile ? '95%' : '600px'"
    :close-on-click-modal="false"
    :class="{ 'mobile-upload-dialog': isMobile }"
    :modal-class="isMobile ? 'mobile-modal' : ''"
  >
    <FileUploader @upload-success="handleUploadSuccess" />
  </el-dialog>
  
  <!-- 文件预览对话框 -->
  <el-dialog
    v-model="showPreviewDialog"
    title="文件预览"
    width="80%"
    :close-on-click-modal="true"
  >
    <FilePreview v-if="previewFile" :file="previewFile" @file-deleted="handleFileDeleted" />
  </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import {
  FolderOpened,
  Upload,
  Picture,
  VideoPlay,
  Folder,
  FolderAdd,
  Search,
  TrendCharts,
  PieChart,
  Setting,
  Download,
  Lightning,
  Share,
  CircleCheck,
  Refresh
} from '@element-plus/icons-vue'
import { useAuthStore } from '@/stores/auth'
import { useFilesStore } from '@/stores/files'
import { formatFileSize, getStorageUsageColor, formatPercentage } from '@/utils/helpers'
import api from '@/utils/api'
import FileUploader from '@/components/FileUploader.vue'
import FilePreview from '@/components/FilePreview.vue'

const router = useRouter()
const authStore = useAuthStore()
const filesStore = useFilesStore()

const showUploadDialog = ref(false)
const showPreviewDialog = ref(false)
const previewFile = ref(null)
const loadingTrends = ref(false)

// 移动端弧形轮播
const carouselRef = ref<HTMLElement | null>(null)
const currentArcIndex = ref(0)
const welcomeArcIndex = ref(0)
let touchStartX = 0
let touchStartY = 0

// 轮播数据（从 stats 响应式计算）
const statCards = computed(() => [
  // 存储类型详情（对应 storage-breakdown）
  { key: 'imgSize', label: '图片占用', value: formatFileSize(stats.value.imageSize), detail: `${stats.value.imageCount} 个文件`, icon: Picture, color: '#60a5fa', cls: 'img-size-card', percentage: Number(stats.value.changes?.images?.percentage) || 0 },
  { key: 'vidSize', label: '视频占用', value: formatFileSize(stats.value.videoSize), detail: `${stats.value.videoCount} 个文件`, icon: VideoPlay, color: '#f87171', cls: 'vid-size-card', percentage: Number(stats.value.changes?.videos?.percentage) || 0 },
  { key: 'motSize', label: '动图/实况', value: formatFileSize(stats.value.motionSize || 0), detail: `${stats.value.motionCount || 0} 个文件`, icon: CircleCheck, color: '#c084fc', cls: 'mot-size-card', percentage: 0 },
  // 分类统计卡片
  { key: 'images', label: '图片文件', value: stats.value.imageCount, detail: formatFileSize(stats.value.imageSize), icon: Picture, color: '#3b82f6', cls: 'image-card', percentage: Number(stats.value.changes?.images?.percentage) || 0 },
  { key: 'videos', label: '视频文件', value: stats.value.videoCount, detail: formatFileSize(stats.value.videoSize), icon: VideoPlay, color: '#ef4444', cls: 'video-card', percentage: Number(stats.value.changes?.videos?.percentage) || 0 },
  { key: 'motion', label: '动图/实况', value: stats.value.motionCount || 0, detail: formatFileSize(stats.value.motionSize || 0), icon: CircleCheck, color: '#a855f7', cls: 'motion-card', percentage: Number(stats.value.changes?.videos?.percentage) || 0 },
  { key: 'folders', label: '文件夹', value: stats.value.folderCount, detail: `${stats.value.totalFiles} 个文件`, icon: Folder, color: '#10b981', cls: 'folder-card', percentage: Number(stats.value.changes?.folders?.percentage) || 0 },
])

// 欢迎区统计轮播数据（对应 welcome-stats 的 3 项）
const welcomeStatCards = computed(() => [
  { key: 'totalFiles', label: '总文件数', value: stats.value.totalFiles, detail: '全部文件', icon: FolderOpened, color: '#34d399' },
  { key: 'totalSize', label: '已用空间', value: formatFileSize(stats.value.totalSize), detail: '存储空间', icon: CircleCheck, color: '#fbbf24' },
  { key: 'storageUsage', label: '使用率', value: formatPercentage(authStore.storageUsage), detail: '空间使用率', icon: TrendCharts, color: '#f472b6' },
])

// 统计数据
interface TrendData {
  total_files: number
  total_size: number
  trend_date: string
}

const stats = ref<{
  imageCount: number
  videoCount: number
  folderCount: number
  totalFiles: number
  totalSize: number
  imageSize: number
  videoSize: number
  motionCount: number
  motionSize: number
  changes: {
    files: { value: number; percentage: number }
    size: { value: number; percentage: number }
    images: { value: number; percentage: number }
    videos: { value: number; percentage: number }
    folders: { value: number; percentage: number }
  }
  trends: TrendData[]
}>({
  imageCount: 0,
  videoCount: 0,
  folderCount: 0,
  totalFiles: 0,
  totalSize: 0,
  imageSize: 0,
  videoSize: 0,
  motionCount: 0,
  motionSize: 0,
  changes: {
    files: { value: 0, percentage: 0 },
    size: { value: 0, percentage: 0 },
    images: { value: 0, percentage: 0 },
    videos: { value: 0, percentage: 0 },
    folders: { value: 0, percentage: 0 }
  },
  trends: []
})

// 当前日期
const currentDate = computed(() => {
  const now = new Date()
  return now.toLocaleDateString('zh-CN', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    weekday: 'long'
  })
})

// 响应式检测
