      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    
    .stat-label {
      font-size: 15px;
      opacity: 0.9;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      text-align: center;
    }
  }
  
  @media (max-width: 768px) {
    gap: 16px;
    margin-top: 20px;
    
    .stat-item {
      padding: 16px 20px;
      min-width: 100px;
      
      .stat-value {
        font-size: 24px;
      }
      
      .stat-label {
        font-size: 12px;
      }
    }
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0px) rotate(0deg);
  }
  50% {
    transform: translateY(-20px) rotate(180deg);
  }
}

// 添加更多动画效果
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes pulse {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
}

@keyframes shimmer {
  0% {
    background-position: -200px 0;
  }
  100% {
    background-position: calc(200px + 100%) 0;
  }
}

// 页面加载动画
.dashboard {
  animation: fadeInUp 0.8s ease-out;
}

.welcome-section {
  animation: fadeInUp 0.6s ease-out 0.2s both;
}

.stats-grid {
  .stat-card {
    animation: slideInLeft 0.6s ease-out both;
    
    &:nth-child(1) { animation-delay: 0.1s; }
    &:nth-child(2) { animation-delay: 0.2s; }
    &:nth-child(3) { animation-delay: 0.3s; }
    &:nth-child(4) { animation-delay: 0.4s; }
  }
}

// 按钮点击动画
.action-btn {
  &:active {
    animation: pulse 0.2s ease-in-out;
  }
}

// 统计卡片悬停效果增强
.stat-card {
        &:hover {
    .stat-icon {
      transform: scale(1.1) rotate(5deg);
    }
    
    .stat-number {
      transform: scale(1.05);
    }
  }
  
  .stat-icon {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }
  
  .stat-number {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }
}

// 加载状态动画
.loading-shimmer {
  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
  background-size: 200px 100%;
  animation: shimmer 1.5s infinite;
}

// 响应式动画优化
@media (prefers-reduced-motion: reduce) {
  .dashboard,
  .welcome-section,
  .stat-card,
  .action-btn {
    animation: none;
  }
  
  .welcome-section::after {
    animation: none;
  }
  
  .stat-card:hover {
    transform: none;
  }
  
  .action-btn:hover {
    transform: none;
  }
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
  margin-top: 32px;
}

// 桌面端统计网格：桌面端显示，移动端隐藏
.stats-grid-desktop {
  display: grid;
}

@media (max-width: 768px) {
  .stats-grid-desktop {
    display: none !important;
  }
}

// 弧形轮播：桌面端隐藏，移动端显示
.stats-arc-carousel {
  display: none;
}

// 移动端弧形轮播卡片定位（基于 DOM 顺序 + active 状态）
@media (max-width: 768px) {
  .stats-arc-carousel {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 12px 0 20px;
    position: relative;
    overflow: hidden;

    .arc-track {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0;
      padding: 16px 0;
      width: 100%;
      position: relative;
      perspective: 900px;
      perspective-origin: 50% 60%;
      height: 180px;
    }

    .arc-card {
      position: absolute;
      width: 78%;
      max-width: 290px;
      border-radius: 20px;
      background: rgba(255, 255, 255, 0.14);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
      border: 1px solid rgba(255, 255, 255, 0.22);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.35);
      padding: 20px;
      transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.5s ease, filter 0.5s ease, box-shadow 0.5s ease;
      cursor: pointer;
      will-change: transform, opacity, filter;
      transform-origin: center bottom;
      left: 50%;
      top: 50%;
      margin-left: -39%;

      // 中心卡片（当前选中）
      &.active {
        transform: translateX(0) translateY(-50%) scale(1) translateZ(0);
        opacity: 1;
        filter: blur(0);
        z-index: 5;
        box-shadow: 0 20px 60px rgba(0, 0, 0, 0.25), 0 0 0 2px rgba(255, 255, 255, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.4);
      }

      // 右侧卡片
      &.right-1 {
        transform: translateX(88%) translateY(-50%) scale(0.8) translateZ(-60px);
        opacity: 0.45;
        filter: blur(3px);
        z-index: 3;
      }
      &.right-2 {
        transform: translateX(176%) translateY(-50%) scale(0.62) translateZ(-110px);
        opacity: 0.2;
        filter: blur(6px);
        z-index: 2;
      }
      &.right-3 {
        transform: translateX(264%) translateY(-50%) scale(0.48) translateZ(-150px);
        opacity: 0;
        filter: blur(9px);
        z-index: 1;
      }

      // 左侧卡片
      &.left-1 {
        transform: translateX(-88%) translateY(-50%) scale(0.8) translateZ(-60px);
        opacity: 0.45;
        filter: blur(3px);
        z-index: 3;
      }
      &.left-2 {
        transform: translateX(-176%) translateY(-50%) scale(0.62) translateZ(-110px);
        opacity: 0.2;
        filter: blur(6px);
        z-index: 2;
      }
      &.left-3 {
        transform: translateX(-264%) translateY(-50%) scale(0.48) translateZ(-150px);
        opacity: 0;
        filter: blur(9px);
        z-index: 1;
      }

      // 图标颜色
      &.image-card .arc-icon { color: #60a5fa; }
      &.video-card .arc-icon { color: #f87171; }
      &.motion-card .arc-icon { color: #c084fc; }
      &.folder-card .arc-icon { color: #34d399; }
      &.img-size-card .arc-icon { color: #60a5fa; }
      &.vid-size-card .arc-icon { color: #f87171; }
      &.mot-size-card .arc-icon { color: #c084fc; }

      .arc-card-inner {
        display: flex;
        flex-direction: column;
        gap: 6px;

        .arc-card-header {
          display: flex;
          align-items: center;
          justify-content: space-between;
          margin-bottom: 4px;

          .arc-icon {
            font-size: 26px;
            display: flex;
            align-items: center;
          }

          .arc-trend {
            display: flex;
            align-items: center;
            gap: 3px;
            font-size: 11px;
            font-weight: 700;
            padding: 3px 8px;
            border-radius: 20px;

            .el-icon {
              font-size: 12px;
            }

            &.trend-positive {
              color: #4ade80;
              background: rgba(74, 222, 128, 0.18);
            }
            &.trend-negative {
              color: #f87171;
              background: rgba(248, 113, 113, 0.18);
            }
          }
        }

        .arc-number {
          font-size: 36px;
          font-weight: 800;
          color: #ffffff;
          line-height: 1;
          text-shadow: 0 2px 10px rgba(0, 0, 0, 0.35);
          letter-spacing: -0.02em;
        }

        .arc-label {
          font-size: 14px;
          font-weight: 600;
          color: rgba(255, 255, 255, 0.85);
        }

        .arc-detail {
          font-size: 11px;
          color: rgba(255, 255, 255, 0.5);
        }
      }
    }

    // 指示点
    .arc-indicators {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      padding: 10px 0 4px;

      .arc-dot {
        width: 6px;
        height: 6px;
        border-radius: 3px;
        background: rgba(255, 255, 255, 0.3);
        transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        cursor: pointer;

        &.active {
          width: 22px;
          background: #ffffff;
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.6);
        }
      }
    }

    // 滑动提示
    .arc-hint {
      font-size: 11px;
      color: rgba(255, 255, 255, 0.35);
      letter-spacing: 0.06em;
      padding-top: 4px;
    }
  }

  // 欢迎区移动端样式
  .welcome-stats {
    // 桌面端横排隐藏，移动端由 welcome-arc-wrapper 显示
    .desktop-stat-item {
      display: none;
    }

    .welcome-arc-wrapper {
      display: block;
      width: 100%;

      .arc-track {
        height: 140px;
      }

      .arc-card {
        width: 70%;
        max-width: 260px;
        margin-left: -35%;
      }
    }
  }

  // 存储详情移动端隐藏，由弧形轮播替代
  .storage-breakdown {
    display: none;
  }
}

.stat-card {
  background: white;
  border-radius: 20px;
  padding: 28px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.08);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid rgba(0, 0, 0, 0.1);
  position: relative;
  overflow: hidden;
  
  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: linear-gradient(90deg, #374151, #111827);
    opacity: 0;
    transition: opacity 0.3s ease;
  }
  
  &:hover {
    transform: translateY(-8px) scale(1.02);
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.15);
    border-color: rgba(0, 0, 0, 0.2);
    
    &::before {
      opacity: 1;
    }
  }
  overflow: hidden;
  
  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
  }
  
  &.image-card {
    .card-header .stat-icon {
      background: linear-gradient(135deg, #f3f4f6, #e5e7eb);
