      background: linear-gradient(135deg, #9ca3af, #6b7280);
    }
  }
  
  &.folder-card {
    .card-header .stat-icon {
      background: linear-gradient(135deg, #d1d5db, #9ca3af);
    }
  }
  
  &.storage-card {
    .card-header .stat-icon {
      background: linear-gradient(135deg, #9ca3af, #6b7280);
    }
  }
  
  .card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
    
